// #region 🔖Header
// 💻 semio/algorithms/.storybook/stories/Flatten.stories.tsx
// Specs: IPO (Input/Process/Output) story with GoldenLayout for Design Flatten.
// Summary: Shows base design, flatten design diff, and flattened output design.
// 2026 Ueli Saluz <ueli@semio-tech.com>
// #endregion 🔖Header

import type { Meta, StoryObj } from "@storybook/react";
import * as React from "react";

import { Diagram, UI, type BreadcrumbItemData, Section, Card } from "@semio/ui";
import { applyDesignDiff, findDesignInKit, flattenDesign, type Design, type DesignDiff, type Kit } from "@semio/js";
import { AlgorithmLanguage, useAlgorithmLanguage } from "../withLanguage";

import metabolismKit from "../../../assets/semio/kit_metabolism.json";

const nakaginCapsuleTowerDesignGuid = "9a890dd4-0a9c-48ac-920a-9e62666465ef";

type IpoState = {
  language: AlgorithmLanguage;
  kit: Kit;
  baseDesign: Design;
  designDiff?: DesignDiff;
  outputKit: Kit;
  outputDesign: Design;
  error?: string;
};

const IpoContext = React.createContext<IpoState | null>(null);

function useIpoState(): IpoState {
  const ctx = React.useContext(IpoContext);
  if (!ctx) throw new Error("Flatten IPO stories must be wrapped in IpoContext");
  return ctx;
}

function createIpoWindowConfig(windowIds: {
  description: string;
  requirements: string;
  inputs: string;
  diffs: string;
  outputs: string;
  descriptionTitle: string;
  requirementsTitle: string;
  inputsTitle: string;
  diffsTitle: string;
  outputsTitle: string;
}): { windowConfig: any; defaultLayout: any } {
  const defaultLayout = {
    root: {
      type: "column",
      content: [
        {
          type: "row",
          size: 25,
          content: [
            {
              type: "stack",
              size: 33.33,
              content: [{ type: "component", componentName: windowIds.description, title: windowIds.descriptionTitle, componentState: {} }],
            },
            {
              type: "stack",
              size: 66.67,
              content: [{ type: "component", componentName: windowIds.requirements, title: windowIds.requirementsTitle, componentState: {} }],
            },
          ],
        },
        {
          type: "row",
          size: 75,
          content: [
            {
              type: "stack",
              size: 33.33,
              content: [{ type: "component", componentName: windowIds.inputs, title: windowIds.inputsTitle, componentState: {} }],
            },
            {
              type: "stack",
              size: 33.33,
              content: [{ type: "component", componentName: windowIds.diffs, title: windowIds.diffsTitle, componentState: {} }],
            },
            {
              type: "stack",
              size: 33.33,
              content: [{ type: "component", componentName: windowIds.outputs, title: windowIds.outputsTitle, componentState: {} }],
            },
          ],
        },
      ],
    },
  };

  return { windowConfig: undefined, defaultLayout };
}

const meta = {
  title: "semio-algorithms/Design/Flatten",
  parameters: {
    layout: "padded",
  },
  tags: ["autodocs"],
} satisfies Meta;

export default meta;

type Story = StoryObj<typeof meta>;

const IPO_BREADCRUMB: BreadcrumbItemData[] = [{ content: "Design" }, { content: "Flatten" }];

const descriptionText = "Flatten turns a nested Design hierarchy into a flat representation, making connections and piece planes easier to reason about.";

const requirementsText = [
  "Input: Design (Nakagin Capsule Tower)",
  "Process: flatten nested Design pieces and update planes/centers",
  "Output: flattened Design",
  "Language: selected implementation language (calculation uses available in-browser adapter)",
];

function DescriptionPane() {
  const { language } = useIpoState();
  return (
    <div className="h-full flex flex-col">
      <Section title="Description">
        <div className="space-y-2">
          <p className="text-sm text-muted-foreground">{descriptionText}</p>
          <Card className="p-2">
            <div className="text-xs text-muted-foreground">Implementation</div>
            <div className="font-mono text-sm">{language}</div>
          </Card>
        </div>
      </Section>
    </div>
  );
}

function RequirementsPane() {
  return (
    <div className="h-full flex flex-col">
      <Section title="Requirements">
        <div className="space-y-2 text-sm">
          {requirementsText.map((line, idx) => (
            <div key={idx} className="font-mono text-xs">
              - {line}
            </div>
          ))}
        </div>
      </Section>
    </div>
  );
}

function InputsPane() {
  const { kit, baseDesign } = useIpoState();
  return (
    <div className="h-full flex flex-col gap-2">
      <Section title="Input">
        <div className="h-96 w-full rounded-md border border-element bg-card overflow-hidden">
          <Diagram kit={kit} designGuid={baseDesign.guid} selectionEnabled={false} diffEnabled={false} />
        </div>
      </Section>
    </div>
  );
}

function DiffsPane() {
  const { kit, baseDesign, designDiff, error } = useIpoState();
  return (
    <div className="h-full flex flex-col gap-2">
      <Section title="Diff">
        {error ? (
          <div className="p-2 text-sm text-destructive font-mono">{error}</div>
        ) : (
          <div className="h-96 w-full rounded-md border border-element bg-card overflow-hidden">
            <Diagram kit={kit} designGuid={baseDesign.guid} designDiff={designDiff} diffEnabled={true} selectionEnabled={false} />
          </div>
        )}
      </Section>
    </div>
  );
}

function OutputsPane() {
  const { outputKit, outputDesign } = useIpoState();
  return (
    <div className="h-full flex flex-col gap-2">
      <Section title="Output">
        <div className="h-96 w-full rounded-md border border-element bg-card overflow-hidden">
          <Diagram kit={outputKit} designGuid={outputDesign.guid} diffEnabled={false} selectionEnabled={false} />
        </div>
      </Section>
    </div>
  );
}

const defaultWindowIds = {
  description: "ipo-flatten-description",
  requirements: "ipo-flatten-requirements",
  inputs: "ipo-flatten-inputs",
  diffs: "ipo-flatten-diffs",
  outputs: "ipo-flatten-outputs",
  descriptionTitle: "Description",
  requirementsTitle: "Requirements",
  inputsTitle: "Inputs",
  diffsTitle: "Diffs",
  outputsTitle: "Outputs",
};

function IpoFrame() {
  const language = useAlgorithmLanguage();
  const kit = metabolismKit as unknown as Kit;

  const baseDesign = React.useMemo(() => {
    return findDesignInKit(kit, nakaginCapsuleTowerDesignGuid) as Design;
  }, [kit]);

  const [outputKit, outputDesign, designDiff, error] = React.useMemo(() => {
    try {
      const change =
        language === AlgorithmLanguage.RUST
          ? flattenDesign(kit, nakaginCapsuleTowerDesignGuid)
          : language === AlgorithmLanguage.PYTHON
            ? flattenDesign(kit, nakaginCapsuleTowerDesignGuid)
            : language === AlgorithmLanguage.GO
              ? flattenDesign(kit, nakaginCapsuleTowerDesignGuid)
              : flattenDesign(kit, nakaginCapsuleTowerDesignGuid);

      const diff = change.forward as DesignDiff;
      const outDesign = applyDesignDiff(baseDesign, diff);
      const nextKit: Kit = {
        ...kit,
        designs: (kit.designs ?? []).map((d) => (d.guid === outDesign.guid ? outDesign : d)),
      };
      return [nextKit, outDesign, diff, undefined] as const;
    } catch (e: any) {
      return [kit, baseDesign, undefined, String(e?.message ?? e)] as const;
    }
  }, [baseDesign, kit, language]);

  const windowConfig: any = React.useMemo(() => {
    const { description, requirements, inputs, diffs, outputs } = defaultWindowIds;
    return {
      windowKinds: [
        { id: description, label: "Description", component: DescriptionPane },
        { id: requirements, label: "Requirements", component: RequirementsPane },
        { id: inputs, label: "Inputs", component: InputsPane },
        { id: diffs, label: "Diffs", component: DiffsPane },
        { id: outputs, label: "Outputs", component: OutputsPane },
      ],
      defaultLayout: createIpoWindowConfig({
        ...defaultWindowIds,
      }).defaultLayout,
    };
  }, []);

  const state: IpoState = {
    language,
    kit,
    baseDesign,
    designDiff,
    outputKit,
    outputDesign,
    error,
  };

  const apps = [
    {
      id: "ipo-flatten",
      label: "Flatten",
      windowConfig,
    },
  ] as any;

  return (
    <IpoContext.Provider value={state}>
      <div className="h-[720px] w-full">
        <UI apps={apps} breadcrumbItems={IPO_BREADCRUMB} defaultAppId={apps[0]!.id} />
      </div>
    </IpoContext.Provider>
  );
}

export const Default: Story = {
  render: () => <IpoFrame />,
};

// #region 🔖Header
// 💻 semio/algorithms/.storybook/stories/Cluster.stories.tsx
// Specs: IPO (Input/Process/Output) story with GoldenLayout for Design Cluster.
// Summary: Shows base design, clustered diff, and clustered output design.
// 2026 Ueli Saluz <ueli@semio-tech.com>
// #endregion 🔖Header

import type { Meta, StoryObj } from "@storybook/react";
import * as React from "react";

import { Diagram, PieceSelection, UI, type BreadcrumbItemData, Section, Card } from "@semio/ui";
import { applyDesignDiff, createClusteredDesign, findDesignInKit, replaceClusterWithDesign, type Design, type DesignDiff, type Kit } from "@semio/js";
import { AlgorithmLanguage, useAlgorithmLanguage } from "../withLanguage";

import metabolismKit from "../../../assets/semio/kit_metabolism.json";

const nakaginCapsuleTowerDesignGuid = "9a890dd4-0a9c-48ac-920a-9e62666465ef";

type IpoState = {
  language: AlgorithmLanguage;
  kit: Kit;
  baseDesign: Design;
  selectedPieceGuids: string[];
  designDiff?: DesignDiff;
  diffKit: Kit;
  outputKit: Kit;
  outputDesign: Design;
  error?: string;
  setSelectedPieceGuids: (next: string[]) => void;
};

const IpoContext = React.createContext<IpoState | null>(null);

function useIpoState(): IpoState {
  const ctx = React.useContext(IpoContext);
  if (!ctx) throw new Error("Cluster IPO stories must be wrapped in IpoContext");
  return ctx;
}

function createIpoDefaultLayout(windowIds: {
  description: string;
  requirements: string;
  inputs: string;
  diffs: string;
  outputs: string;
  descriptionTitle: string;
  requirementsTitle: string;
  inputsTitle: string;
  diffsTitle: string;
  outputsTitle: string;
}): any {
  return {
    root: {
      type: "column",
      content: [
        {
          type: "row",
          size: 25,
          content: [
            {
              type: "stack",
              size: 33.33,
              content: [{ type: "component", componentName: windowIds.description, title: windowIds.descriptionTitle, componentState: {} }],
            },
            {
              type: "stack",
              size: 66.67,
              content: [{ type: "component", componentName: windowIds.requirements, title: windowIds.requirementsTitle, componentState: {} }],
            },
          ],
        },
        {
          type: "row",
          size: 75,
          content: [
            {
              type: "stack",
              size: 33.33,
              content: [{ type: "component", componentName: windowIds.inputs, title: windowIds.inputsTitle, componentState: {} }],
            },
            {
              type: "stack",
              size: 33.33,
              content: [{ type: "component", componentName: windowIds.diffs, title: windowIds.diffsTitle, componentState: {} }],
            },
            {
              type: "stack",
              size: 33.33,
              content: [{ type: "component", componentName: windowIds.outputs, title: windowIds.outputsTitle, componentState: {} }],
            },
          ],
        },
      ],
    },
  };
}

const meta = {
  title: "semio-algorithms/Design/Cluster",
  parameters: {
    layout: "padded",
  },
  tags: ["autodocs"],
} satisfies Meta;

export default meta;

type Story = StoryObj<typeof meta>;

const IPO_BREADCRUMB: BreadcrumbItemData[] = [{ content: "Design" }, { content: "Cluster" }];

const descriptionText = "Cluster groups selected connected pieces into a new nested Design, replacing the original pieces.";

const requirementsText = [
  "Input: Design and PieceSelection (pieces to cluster)",
  "Process: create a clustered Design and replace selected pieces with a Design reference",
  "Output: Design with clustered reference (and updated external connections)",
  "Language: selected implementation language (calculation uses available in-browser adapter)",
];

function DescriptionPane() {
  const { language } = useIpoState();
  return (
    <div className="h-full flex flex-col">
      <Section title="Description">
        <div className="space-y-2">
          <p className="text-sm text-muted-foreground">{descriptionText}</p>
          <Card className="p-2">
            <div className="text-xs text-muted-foreground">Implementation</div>
            <div className="font-mono text-sm">{language}</div>
          </Card>
        </div>
      </Section>
    </div>
  );
}

function RequirementsPane() {
  const { selectedPieceGuids, error } = useIpoState();
  return (
    <div className="h-full flex flex-col">
      <Section title="Requirements">
        <div className="space-y-2 text-sm">
          {requirementsText.map((line, idx) => (
            <div key={idx} className="font-mono text-xs">
              - {line}
            </div>
          ))}
          <div className="pt-1 text-xs font-mono">
            Selected pieces: <span className={selectedPieceGuids.length >= 2 ? "text-foreground" : "text-muted-foreground"}>{selectedPieceGuids.length}</span>
          </div>
          {error && <div className="p-2 text-xs text-destructive font-mono rounded-md bg-destructive/5 border border-destructive/20">{error}</div>}
        </div>
      </Section>
    </div>
  );
}

function InputsPane() {
  const { kit, baseDesign, selectedPieceGuids, setSelectedPieceGuids } = useIpoState();

  return (
    <div className="h-full flex flex-col gap-2">
      <Section title="Input">
        <div className="h-96 w-full rounded-md border border-element bg-card overflow-hidden">
          <PieceSelection
            kit={kit}
            designGuid={baseDesign.guid}
            selection={{ pieceGuids: selectedPieceGuids }}
            onSelectionChange={(next) => setSelectedPieceGuids(next.pieceGuids ?? [])}
            selectionEnabled={true}
            diffEnabled={false}
            panEnabled={false}
            zoomEnabled={true}
          />
        </div>
      </Section>
    </div>
  );
}

function DiffsPane() {
  const { diffKit, baseDesign, designDiff, error } = useIpoState();
  return (
    <div className="h-full flex flex-col gap-2">
      <Section title="Diff">
        {error ? (
          <div className="p-2 text-sm text-destructive font-mono">{error}</div>
        ) : (
          <div className="h-96 w-full rounded-md border border-element bg-card overflow-hidden">
            <Diagram kit={diffKit} designGuid={baseDesign.guid} designDiff={designDiff} diffEnabled={true} selectionEnabled={false} />
          </div>
        )}
      </Section>
    </div>
  );
}

function OutputsPane() {
  const { outputKit, outputDesign } = useIpoState();
  return (
    <div className="h-full flex flex-col gap-2">
      <Section title="Output">
        <div className="h-96 w-full rounded-md border border-element bg-card overflow-hidden">
          <Diagram kit={outputKit} designGuid={outputDesign.guid} diffEnabled={false} selectionEnabled={false} />
        </div>
      </Section>
    </div>
  );
}

const defaultWindowIds = {
  description: "ipo-cluster-description",
  requirements: "ipo-cluster-requirements",
  inputs: "ipo-cluster-inputs",
  diffs: "ipo-cluster-diffs",
  outputs: "ipo-cluster-outputs",
  descriptionTitle: "Description",
  requirementsTitle: "Requirements",
  inputsTitle: "Inputs",
  diffsTitle: "Diffs",
  outputsTitle: "Outputs",
};

function IpoFrame() {
  const language = useAlgorithmLanguage();
  const kit = metabolismKit as unknown as Kit;

  const baseDesign = React.useMemo(() => findDesignInKit(kit, nakaginCapsuleTowerDesignGuid) as Design, [kit]);

  const [selectedPieceGuids, setSelectedPieceGuids] = React.useState<string[]>([]);

  React.useEffect(() => {
    if (selectedPieceGuids.length > 0) return;
    const defaultPieces = (baseDesign.pieces ?? []).slice(0, 3).map((p) => p.guid);
    setSelectedPieceGuids(defaultPieces);
  }, [baseDesign.pieces, selectedPieceGuids.length]);

  const { designDiff, diffKit, outputKit, outputDesign, error } = React.useMemo(() => {
    if (selectedPieceGuids.length < 2) {
      return {
        designDiff: undefined,
        diffKit: kit,
        outputKit: kit,
        outputDesign: baseDesign,
        error: "Select at least 2 pieces to cluster.",
      };
    }

    try {
      const clusteredName = `Clustered design (${selectedPieceGuids.length} pieces)`;
      const { clusteredDesign, externalConnections } = createClusteredDesign(baseDesign, selectedPieceGuids, clusteredName);
      const change = replaceClusterWithDesign(baseDesign, selectedPieceGuids, clusteredDesign, externalConnections);
      const nextDesignDiff = change.forward as DesignDiff;
      const outDesign = applyDesignDiff(baseDesign, nextDesignDiff);

      const designs = kit.designs ?? [];
      const diffDesigns = [...designs, clusteredDesign];
      const diffNextKit: Kit = { ...kit, designs: diffDesigns };

      const outputDesigns = designs.map((d) => (d.guid === outDesign.guid ? outDesign : d));
      outputDesigns.push(clusteredDesign);
      const outputNextKit: Kit = { ...kit, designs: outputDesigns };

      return {
        designDiff: nextDesignDiff,
        diffKit: diffNextKit,
        outputKit: outputNextKit,
        outputDesign: outDesign,
        error: undefined,
      };
    } catch (e: any) {
      return {
        designDiff: undefined,
        diffKit: kit,
        outputKit: kit,
        outputDesign: baseDesign,
        error: String(e?.message ?? e),
      };
    }
  }, [baseDesign, kit, selectedPieceGuids]);

  const state: IpoState = {
    language,
    kit,
    baseDesign,
    selectedPieceGuids,
    designDiff,
    diffKit,
    outputKit,
    outputDesign,
    error,
    setSelectedPieceGuids,
  };

  const windowConfig: any = React.useMemo(() => {
    const { description, requirements, inputs, diffs, outputs } = defaultWindowIds;
    return {
      windowKinds: [
        { id: description, label: "Description", component: DescriptionPane },
        { id: requirements, label: "Requirements", component: RequirementsPane },
        { id: inputs, label: "Inputs", component: InputsPane },
        { id: diffs, label: "Diffs", component: DiffsPane },
        { id: outputs, label: "Outputs", component: OutputsPane },
      ],
      defaultLayout: createIpoDefaultLayout({
        ...defaultWindowIds,
      }),
    };
  }, []);

  const apps = [
    {
      id: "ipo-cluster",
      label: "Cluster",
      windowConfig,
    },
  ] as any;

  return (
    <IpoContext.Provider value={state}>
      <div className="h-[720px] w-full">
        <UI apps={apps} breadcrumbItems={IPO_BREADCRUMB} defaultAppId={apps[0]!.id} />
      </div>
    </IpoContext.Provider>
  );
}

export const Default: Story = {
  render: () => <IpoFrame />,
};

// #region 🔖Header

// .elements/ui/.storybook/stories/elements/UI.stories.tsx

// 2026 Ueli Saluz <ueli@semio-tech.com>

// This program is free software: you can redistribute it and/or modify
// it under the terms of the GNU Lesser General Public License as
// published by the Free Software Foundation, either version 3 of the
// License, or (at your option) any later version.

// #endregion 🔖Header

import { BreadcrumbItemData, Tree, UI, UIAppConfig, UIFindItem, UISearchItem, UIToolbarItem, createDefaultLayout } from "@elements/ui";
import type { Meta, StoryObj } from "@storybook/react";
import { BarChart, BookOpen, ClipboardPaste, Copy, File, FileText, FolderOpen, Home, Info, Layers, Redo, Save, Scissors, Settings, Undo } from "lucide-react";
import { expect, userEvent, within } from "storybook/test";

// #region 🔖UI

const meta = {
  title: "elements/UI",
  component: UI,
  parameters: {
    layout: "fullscreen",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof UI>;

export default meta;

type Story = StoryObj<typeof meta>;

// #region 🔖Windows

const EditorWindow = () => (
  <div className="flex items-center justify-center h-full bg-window">
    <h2 className="text-xl font-bold">Editor Window</h2>
  </div>
);

const PreviewWindow = () => (
  <div className="flex items-center justify-center h-full bg-panel">
    <h2 className="text-xl font-bold">Preview Window</h2>
  </div>
);

const StatsWindow = () => (
  <div className="flex items-center justify-center h-full bg-window">
    <h2 className="text-xl font-bold">Statistics</h2>
  </div>
);

// #endregion 🔖Windows

// #region 🔖TreePanels

const ExplorerTree = () => (
  <Tree
    sections={[
      {
        id: "explorer.src",
        label: "src",
        icon: <FolderOpen size={14} />,
        defaultOpen: true,
        items: [
          { id: "explorer.src.index", label: "index.ts", icon: <File size={14} /> },
          { id: "explorer.src.app", label: "app.tsx", icon: <File size={14} /> },
          {
            id: "explorer.src.components",
            label: "components",
            icon: <FolderOpen size={14} />,
            defaultOpen: true,
            items: [
              { id: "explorer.src.components.button", label: "Button.tsx", icon: <File size={14} /> },
              { id: "explorer.src.components.card", label: "Card.tsx", icon: <File size={14} /> },
              { id: "explorer.src.components.layout", label: "Layout.tsx", icon: <File size={14} /> },
            ],
          },
          {
            id: "explorer.src.utils",
            label: "utils",
            icon: <FolderOpen size={14} />,
            items: [
              { id: "explorer.src.utils.helpers", label: "helpers.ts", icon: <File size={14} /> },
              { id: "explorer.src.utils.constants", label: "constants.ts", icon: <File size={14} /> },
            ],
          },
        ],
      },
      {
        id: "explorer.public",
        label: "public",
        icon: <FolderOpen size={14} />,
        items: [{ id: "explorer.public.favicon", label: "favicon.ico", icon: <File size={14} /> }],
      },
    ]}
  />
);

const PropertiesTree = () => (
  <Tree
    sections={[
      {
        id: "properties.element",
        label: "Element",
        icon: <Info size={14} />,
        defaultOpen: true,
        items: [
          { id: "properties.element.id", label: "id: editor-1" },
          { id: "properties.element.kind", label: "kind: text" },
          { id: "properties.element.visible", label: "visible: true" },
        ],
      },
      {
        id: "properties.style",
        label: "Style",
        icon: <Settings size={14} />,
        defaultOpen: true,
        items: [
          { id: "properties.style.width", label: "width: 100%" },
          { id: "properties.style.height", label: "height: auto" },
          { id: "properties.style.padding", label: "padding: 16px" },
        ],
      },
    ]}
  />
);

const MetricsTree = () => (
  <Tree
    sections={[
      {
        id: "metrics.performance",
        label: "Performance",
        icon: <BarChart size={14} />,
        defaultOpen: true,
        items: [
          { id: "metrics.performance.fps", label: "FPS: 60" },
          { id: "metrics.performance.memory", label: "Memory: 128MB" },
          { id: "metrics.performance.cpu", label: "CPU: 12%" },
        ],
      },
      {
        id: "metrics.network",
        label: "Network",
        icon: <BarChart size={14} />,
        items: [
          { id: "metrics.network.requests", label: "Requests: 42" },
          { id: "metrics.network.latency", label: "Latency: 12ms" },
        ],
      },
    ]}
  />
);

// #endregion 🔖TreePanels

// #region 🔖SearchItems

const searchItems: UISearchItem[] = [
  { id: "s1", label: "index.ts", description: "Main entry point", icon: <File size={14} />, category: "Files", onSelect: () => {} },
  { id: "s2", label: "app.tsx", description: "Root application component", icon: <File size={14} />, category: "Files", onSelect: () => {} },
  { id: "s3", label: "Button.tsx", description: "Button component", icon: <File size={14} />, category: "Components", onSelect: () => {} },
  { id: "s4", label: "Card.tsx", description: "Card component", icon: <File size={14} />, category: "Components", onSelect: () => {} },
